<script setup>
// Reactivity visualizer: every frame is generated by actually running the
// teaching engine (utils/miniReactivity.js) on the selected scenario.
import { computed, shallowRef } from 'vue'
import { createEngine } from '../../utils/miniReactivity.js'
import { presets } from './reactivityPresets.js'
import { useStepPlayer } from '../../composables/useStepPlayer.js'
import AnimationControls from './AnimationControls.vue'
import CodeBlock from '../code/CodeBlock.vue'
import RichText from '../learning/RichText.vue'

const props = defineProps({
  preset: { type: String, default: 'compare' },
})

const STAGES = [
  { id: 'state', label: 'Reactive state' },
  { id: 'track', label: 'Dependency tracking' },
  { id: 'change', label: 'State change' },
  { id: 'trigger', label: 'Trigger' },
  { id: 'effects', label: 'Effects run' },
  { id: 'dom', label: 'DOM updated' },
]

const def = presets[props.preset] ?? presets.compare
let events = []
const consoleLines = []
const engine = createEngine((ev) => events.push(ev))
const scenario = def.setup(engine, (text) => {
  consoleLines.push(text)
  events.push({ type: 'log', text })
})
let lastOutput = ''

const fmt = (v) => (typeof v === 'string' ? `'${v}'` : String(v))
const code = (s) => `\`${s}\``

function buildFrames(list, action, initial) {
  const frames = []
  let output = lastOutput
  const logs = consoleLines.slice(0, initial ? 0 : consoleLines.length - list.filter((e) => e.type === 'log').length)
  const push = (f) => frames.push({ output, logs: [...logs], ...f })
  if (initial) {
    push({ stage: 'state', lines: def.lines.create, focus: [], text: 'Create the reactive state. Nothing is tracked yet — tracking only happens while an effect (like a render) is running.' })
  }
  for (let i = 0; i < list.length; i++) {
    const ev = list[i]
    switch (ev.type) {
      case 'track': {
        const deps = [ev.dep]
        while (list[i + 1]?.type === 'track' && list[i + 1].effect === ev.effect) deps.push(list[++i].dep)
        const unique = [...new Set(deps)]
        push({
          stage: 'track',
          focus: [ev.effect, ...unique],
          lines: ev.kind === 'computed' ? def.lines.computed : ev.kind === 'watch' ? def.lines.watch : def.lines.render,
          text: `While ${code(ev.effect)} runs it reads ${unique.map(code).join(', ')}. Vue records each read as a dependency — this is **tracking**.`,
        })
        break
      }
      case 'set':
        push({ stage: 'change', focus: [ev.dep], lines: action?.line, text: `**${ev.dep}** changes from ${code(fmt(ev.old))} to ${code(fmt(ev.value))}. Writing goes through a setter, so Vue knows.` })
        break
      case 'same':
        push({ stage: 'change', focus: [ev.dep], lines: action?.line, text: `**${ev.dep}** is set to the value it already has (${code(fmt(ev.value))}). Vue compares with ${code('Object.is')}: no change, so nothing is triggered.` })
        break
      case 'trigger':
        push(
          ev.subs.length
            ? { stage: 'trigger', focus: [ev.dep, ...ev.subs], text: `**Trigger:** who depends on ${code(ev.dep)}? → ${ev.subs.map(code).join(', ')}.` }
            : { stage: 'trigger', focus: [ev.dep], text: `**Trigger:** nothing read ${code(ev.dep)} during the last render, so **nothing needs to update**. Tracking is precise, per property.` },
        )
        break
      case 'dirty':
        push({ stage: 'trigger', focus: [ev.effect], lines: def.lines.computed, text: `${code(ev.effect)} is marked **dirty**: its cached value may be stale. It does *not* recompute yet — computeds are lazy and wait until something reads them.` })
        break
      case 'queued':
        push({
          stage: 'effects',
          focus: [ev.effect],
          lines: ev.kind === 'watch' ? def.lines.watch : null,
          text:
            ev.kind === 'render'
              ? 'The component’s **render effect** is queued. Updates are batched: it will run once, on the next tick, however many changes happen right now.'
              : `The watcher ${code(ev.effect)} is queued. By default watchers run *before* the component re-renders (flush: 'pre').`,
        })
        break
      case 'dedupe':
        push({ stage: 'effects', focus: [ev.effect], text: `${code(ev.effect)} is already queued, so it isn’t added twice.` })
        break
      case 'flush':
        push({ stage: 'effects', focus: ev.effects, text: `**Next tick:** Vue flushes the queue — ${ev.effects.map(code).join(', ')} — watchers first, then renders.` })
        break
      case 'idle':
        push({ stage: 'effects', focus: [], text: 'The queue is empty: no effect runs, no re-render, no DOM work at all.' })
        break
      case 'run':
        if (ev.kind === 'render') push({ stage: 'effects', focus: ['render'], lines: def.lines.render, text: 'The **render effect** runs: the template is evaluated again with the current state (and re-tracks what it reads).' })
        else if (ev.kind === 'computed') push({ stage: 'effects', focus: [ev.effect], lines: def.lines.computed, text: `${code(ev.effect)} is read while dirty, so its getter runs now.` })
        else push({ stage: 'effects', focus: [ev.effect], lines: def.lines.watch, text: `${code(ev.effect)} re-runs its source to check whether the watched value changed.` })
        break
      case 'computed':
        push({ stage: 'effects', focus: [ev.effect], lines: def.lines.computed, text: `${code(ev.effect)} = ${code(fmt(ev.value))}, cached until one of its dependencies changes.` })
        break
      case 'cache-hit':
        push({ stage: 'effects', focus: [ev.effect], text: `${code(ev.effect)} is clean, so Vue returns the cached ${code(fmt(ev.value))} **without running the getter again**.` })
        break
      case 'callback':
        push({ stage: 'effects', focus: [ev.effect], lines: def.lines.watch, text: `The watched value changed (${code(fmt(ev.old))} → ${code(fmt(ev.value))}), so the **callback** runs.` })
        break
      case 'unchanged':
        push({ stage: 'effects', focus: [ev.effect], lines: def.lines.watch, text: 'The watched value is the same as before, so the callback is skipped.' })
        break
      case 'log':
        logs.push(ev.text)
        if (frames.length) frames[frames.length - 1].logs = [...logs]
        break
      case 'render': {
        const changed = ev.output !== output
        output = ev.output
        push({
          stage: 'dom',
          focus: ['render'],
          lines: def.lines.render,
          text: changed
            ? `Vue compares the new output with the previous one and **patches only what changed** in the real DOM → “${ev.output}”.`
            : 'The output is identical to before, so there is nothing to patch.',
        })
        break
      }
    }
  }
  lastOutput = output
  return frames
}

engine.effect('render', scenario.render, { kind: 'render' })
const frames = shallowRef(buildFrames(events, null, true))
events = []

const player = useStepPlayer(frames, { interval: 2200 })
const frame = player.frame

function act(action) {
  events = []
  action.run()
  engine.flush()
  frames.value = buildFrames(events, action, false)
  player.restart()
  if (player.canAutoplay.value) player.play()
}

const graph = computed(() => {
  void frames.value // refresh after each action
  return engine.graph().filter((g) => !g.dep.startsWith('__'))
})
const focus = computed(() => new Set(frame.value?.focus ?? []))
const stageIndex = computed(() => STAGES.findIndex((s) => s.id === frame.value?.stage))
const highlight = computed(() => (frame.value?.lines ? [frame.value.lines] : []))
</script>

<template>
  <div class="rv">
    <ol class="rv__pipeline" aria-label="Reactivity pipeline">
      <li
        v-for="(s, i) in STAGES"
        :key="s.id"
        class="rv__stage"
        :class="{ 'is-active': i === stageIndex, 'is-past': i < stageIndex }"
        :aria-current="i === stageIndex ? 'step' : undefined"
      >
        <span class="mono">{{ i + 1 }}</span> {{ s.label }}
      </li>
    </ol>

    <div class="rv__grid">
      <CodeBlock :code="def.code" lang="vue" :title="`${def.title} — the code being modelled`" :highlight="highlight" :copyable="false" />

      <div class="rv__side">
        <div class="rv__panel">
          <p class="label">Dependencies (who reads what)</p>
          <ul class="rv__deps">
            <li v-if="!graph.length" class="muted">nothing tracked yet</li>
            <li v-for="g in graph" :key="g.dep" class="rv__dep">
              <span class="rv__node rv__node--state" :class="{ 'is-focus': focus.has(g.dep) }">{{ g.dep }}</span>
              <span class="rv__arrow" aria-hidden="true">→</span>
              <span v-if="!g.subs.length" class="muted rv__none">no subscribers</span>
              <span v-for="sub in g.subs" :key="sub" class="rv__node" :class="{ 'is-focus': focus.has(sub) }">{{ sub }}</span>
            </li>
          </ul>
        </div>
        <div class="rv__panel rv__dom">
          <p class="label">Rendered DOM</p>
          <p class="rv__out" :class="{ 'is-flash': frame?.stage === 'dom' }">{{ frame?.output || '—' }}</p>
        </div>
        <div v-if="def.lines.watch" class="rv__panel rv__console">
          <p class="label">console</p>
          <p v-if="!frame?.logs?.length" class="muted mono">(empty)</p>
          <p v-for="(l, i) in frame?.logs ?? []" :key="i" class="mono">› {{ l }}</p>
        </div>
      </div>
    </div>

    <div class="rv__explain" aria-live="polite">
      <span class="rv__stage-tag label">{{ STAGES[stageIndex]?.label }}</span>
      <RichText :value="frame?.text ?? ''" />
    </div>

    <div class="rv__controls">
      <AnimationControls :player="player" :label="`${def.title} visualizer`" />
      <div class="rv__actions">
        <span class="label">try a change:</span>
        <button v-for="a in scenario.actions" :key="a.id" type="button" class="btn btn--sm btn--ink mono" @click="act(a)">{{ a.label }}</button>
      </div>
    </div>
    <p class="rv__note muted">A simplified teaching model of Vue’s reactivity (track → trigger → batched flush). Vue’s real implementation differs in detail, but follows the same idea.</p>
  </div>
</template>

